<#
.SYNOPSIS
  Generate a FaultLine service package manifest, or check an existing one.

.DESCRIPTION
  Walks a package directory (produced by one of the build\cmd\*_dist.cmd
  scripts), computes a SHA-256 for every file, and writes manifest.txt at the
  package root. The manifest is the authoritative list of files in the package:
  fl_import uses it to add, update, and -- crucially -- remove stale files in a
  consumer repository.

  The manifest is generated by walking what is actually on disk, so it can never
  drift from the files the dist script copied (provided the dist script wiped
  its output tree first).

  Regeneration is idempotent: when the file list, hashes, version and dependencies
  all match what the existing manifest already records, the previous "generated"
  timestamp is kept rather than refreshed, so an unchanged package yields a
  byte-for-byte identical manifest.

  With -Check the manifest is verified instead of written: the package is scanned
  the same way, the result is compared against what manifest.txt already records,
  and the script exits non-zero describing any difference. Nothing is written. This
  answers "does this manifest still describe this package?" -- a file added to or
  removed from the package, an edited file, or a manifest that was hand-edited.

  Note the scope: -Check compares the manifest against the package directory, not
  against the repository the dist script copies from. To catch sources that changed
  without the package being rebuilt, regenerate and then ask version control whether
  anything moved -- regeneration is idempotent, so it is safe to run at any time:

      build\cmd\all_dist.cmd && git diff --exit-code -- dist

.PARAMETER PackageDir
  Root of the package to scan (e.g. dist\memory). manifest.txt is written here,
  or, with -Check, read from here.

.PARAMETER Check
  Verify the existing manifest against the package instead of writing one. Exits 0
  when the manifest is current, 1 when it is stale or missing.

.PARAMETER Name
  Service name recorded in the manifest (e.g. memory). Required when emitting.
  Optional with -Check, where it is compared against the recorded name if given
  and ignored if not.

.PARAMETER Version
  Package version recorded in the manifest (e.g. 0.2.0). Required when emitting.
  Optional with -Check, where it is compared against the recorded version if given
  and ignored if not.

.PARAMETER Depends
  Space-separated list of service names this package requires. May be empty for
  self-contained packages. With -Check it is compared only if given.

.EXAMPLE
  fl_emit_manifest.ps1 -PackageDir dist\log_service -Name log_service -Version 0.2.0 -Depends stream_service

.EXAMPLE
  fl_emit_manifest.ps1 -Check -PackageDir dist\log_service
#>
[CmdletBinding(DefaultParameterSetName = 'Emit')]
param(
    [Parameter(ParameterSetName = 'Help')]
    [Alias('h')]
    [switch]$Help,

    [Parameter(ParameterSetName = 'Check', Mandatory = $true)]
    [switch]$Check,

    [Parameter(ParameterSetName = 'Emit',  Mandatory = $true)]
    [Parameter(ParameterSetName = 'Check', Mandatory = $true)]
    [string]$PackageDir,

    [Parameter(ParameterSetName = 'Emit',  Mandatory = $true)]
    [Parameter(ParameterSetName = 'Check')]
    [string]$Name,

    [Parameter(ParameterSetName = 'Emit',  Mandatory = $true)]
    [Parameter(ParameterSetName = 'Check')]
    [string]$Version,

    [string]$Depends = ""
)

$ErrorActionPreference = "Stop"

if ($Help) {
    Get-Help $PSCommandPath -Detailed
    exit 0
}

# Compute a lowercase SHA-256 hex digest using .NET directly, so we do not
# depend on Get-FileHash (absent or constrained in some PowerShell hosts).
function Get-Sha256([string]$path) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.IO.File]::ReadAllBytes($path)
        return ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLower()
    } finally {
        $sha.Dispose()
    }
}

if (-not (Test-Path -LiteralPath $PackageDir -PathType Container)) {
    Write-Error "Package directory not found: $PackageDir"
    exit 1
}

# Trailing separators are trimmed because the relative paths below are cut with
# Substring($root.Length + 1), where the +1 skips the separator between the root
# and the rest. A $root that already ends in one would make that +1 eat the first
# character of every path -- and a caller who tab-completes a directory gets a
# trailing separator for free.
$root = (Resolve-Path -LiteralPath $PackageDir).Path.TrimEnd('\', '/')
$manifestPath = Join-Path $root "manifest.txt"

# Everything under the package except the manifest itself and any importer
# tooling that may have been copied alongside it.
$files = Get-ChildItem -LiteralPath $root -Recurse -File |
    Where-Object { $_.Name -ne "manifest.txt" -and $_.Name -notlike "fl_import.*" }

$entries = foreach ($f in $files) {
    $rel = $f.FullName.Substring($root.Length + 1).Replace('\', '/')
    $hash = Get-Sha256 $f.FullName
    [pscustomobject]@{ Rel = $rel; Hash = $hash }
}

# Everything the manifest records apart from its own timestamp.
$head = New-Object System.Collections.Generic.List[string]
$head.Add("# FaultLine service package manifest")
$head.Add("# Generated by build\dist\fl_emit_manifest.ps1 -- do not edit by hand.")
$head.Add("name $Name")
$head.Add("version $Version")
$head.Add("depends $($Depends.Trim())")

# Order the rows by an ordinal comparison rather than Sort-Object, whose
# culture-sensitive collation orders '.' against '_' differently under Windows
# PowerShell 5.1 (NLS) and PowerShell 7+ (ICU). Left to the default, the manifest's
# line order would depend on which host generated it, so the same package would
# compare as changed purely for having been regenerated elsewhere.
$rows = [string[]]@(foreach ($e in $entries) { "f $($e.Rel) $($e.Hash)" })
[Array]::Sort($rows, [System.StringComparer]::Ordinal)
$body = New-Object System.Collections.Generic.List[string]
$body.AddRange($rows)

# -----------------------------------------------------------------------
# Check mode: report how the package differs from what the manifest records,
# and write nothing.
# -----------------------------------------------------------------------
if ($Check) {
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
        Write-Host "  manifest.txt MISSING  ($manifestPath)"
        exit 1
    }

    $recName = $null; $recVersion = $null; $recDepends = ""
    $recRows = @{}
    $recRowLines = New-Object System.Collections.Generic.List[string]
    foreach ($line in [System.IO.File]::ReadAllLines($manifestPath)) {
        if ($line -match '^\s*#') { continue }
        $p = -split $line
        if ($p.Count -lt 2) { continue }
        switch ($p[0]) {
            'name'    { $recName = $p[1]; break }
            'version' { $recVersion = $p[1]; break }
            'depends' { $recDepends = (($p | Select-Object -Skip 1) -join ' '); break }
            'f'       {
                if ($p.Count -ge 3) {
                    $recRows[$p[1]] = $p[2]
                    $recRowLines.Add("f $($p[1]) $($p[2])")
                }
                break
            }
            default   { break }
        }
    }

    $nowRows = @{}
    foreach ($e in $entries) { $nowRows[$e.Rel] = $e.Hash }

    $problems = New-Object System.Collections.Generic.List[string]

    $nowKeys = [string[]]@($nowRows.Keys)
    [Array]::Sort($nowKeys, [System.StringComparer]::Ordinal)
    foreach ($rel in $nowKeys) {
        if (-not $recRows.ContainsKey($rel)) {
            $problems.Add("+ $rel -- in the package, not recorded in the manifest")
        } elseif ($recRows[$rel] -ne $nowRows[$rel]) {
            $problems.Add("~ $rel -- content differs from the recorded hash")
        }
    }

    $recKeys = [string[]]@($recRows.Keys)
    [Array]::Sort($recKeys, [System.StringComparer]::Ordinal)
    foreach ($rel in $recKeys) {
        if (-not $nowRows.ContainsKey($rel)) {
            $problems.Add("- $rel -- recorded in the manifest, not in the package")
        }
    }

    # Same files, different order: still a difference, because the manifest is
    # compared byte-for-byte by everything downstream of it.
    if ($problems.Count -eq 0 -and (($recRowLines -join "`n") -ne ($body -join "`n"))) {
        $problems.Add("! rows record the right files in a different order")
    }

    # Metadata is only checked when the caller supplied it, so that a bare
    # -Check -PackageDir still verifies the file list.
    if ($PSBoundParameters.ContainsKey('Name') -and $recName -ne $Name) {
        $problems.Add("! name: manifest records '$recName', expected '$Name'")
    }
    if ($PSBoundParameters.ContainsKey('Version') -and $recVersion -ne $Version) {
        $problems.Add("! version: manifest records '$recVersion', expected '$Version'")
    }
    if ($PSBoundParameters.ContainsKey('Depends') -and $recDepends -ne $Depends.Trim()) {
        $problems.Add("! depends: manifest records '$recDepends', expected '$($Depends.Trim())'")
    }

    if ($problems.Count -gt 0) {
        Write-Host "  manifest.txt STALE    ($($problems.Count) difference(s), $root)"
        foreach ($problem in $problems) {
            Write-Host "    $problem"
        }
        exit 1
    }

    Write-Host "  manifest.txt current  ($(@($entries).Count) files, version $recVersion)"
    exit 0
}

# Keep the previous timestamp when nothing else in the manifest moved, so that
# regenerating an unchanged package leaves its manifest byte-for-byte identical.
# Otherwise every run rewrites this one line, and anything watching the manifest
# for real changes -- version control, or a consumer comparing its imported copy
# against a fresh package -- sees a change on every run.
$generated = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
$reused = $false
if (Test-Path -LiteralPath $manifestPath -PathType Leaf) {
    $prev      = @([System.IO.File]::ReadAllLines($manifestPath))
    $prevStamp = @($prev | Where-Object { $_ -match '^generated\s' })
    $prevRest  = @($prev | Where-Object { $_ -notmatch '^generated\s' })
    $nowRest   = @($head) + @($body)
    if ($prevStamp.Count -eq 1 -and (($prevRest -join "`n") -eq ($nowRest -join "`n"))) {
        if ($prevStamp[0] -match '^generated\s+(\S+)\s*$') {
            $generated = $Matches[1]
            $reused = $true
        }
    }
}

$lines = New-Object System.Collections.Generic.List[string]
$lines.AddRange($head)
$lines.Add("generated $generated")
$lines.AddRange($body)

# Write LF line endings and no BOM so the manifest parses identically under
# bash (sha256sum/read) and PowerShell. Set-Content -Encoding UTF8 would emit
# CRLF + a BOM on Windows PowerShell 5.1.
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($manifestPath, ($lines -join "`n") + "`n", $utf8NoBom)
$state = if ($reused) { "unchanged" } else { "written  " }
Write-Host "  manifest.txt $state ($(@($entries).Count) files, version $Version)"

# Exit explicitly so a caller can read $LASTEXITCODE after every path, not just
# the failing ones.
exit 0
